      "text": "Sarvottam Cables manufactures power cables, wires and conductors; results are for Q1 FY27 (quarter ended 30 June 2026).",
      "citations": ["S3"],
      "evidence": [{"id": "S3:E1"}]
    },
    {
      "text": "Official consolidated revenue was ₹1,248 crore, up 18.0% year-on-year.",
      "citations": ["S3"],
      "evidence": [{"id": "S3:E3"}]
    },
    {
      "text": "Profit after tax was ₹82 crore, up 5.9% year-on-year.",
      "citations": ["S3"],
      "evidence": [{"id": "S3:E6"}]
    },
    {
      "text": "EBITDA margin was 11.2%, down 170 bps from 12.9% a year earlier.",
      "citations": ["S3"],
      "evidence": [{"id": "S3:E5"}]
    }
  ],
  "Bull case": [
    {
      "text": "Order book stood at ₹3,900 crore as of 30 June 2026, up from ₹3,150 crore a year ago.",
      "citations": ["S3"],
      "evidence": [{"id": "S3:E7"}]
    },
    {
      "text": "The company says the Bharuch plant, adding about 30% to cable capacity, is on track for Q3 FY27 commercial production; the MD maintains FY27 revenue growth guidance of 15–17%.",
      "citations": ["S3", "S2"],
      "evidence": [{"id": "S3:E9"}, {"id": "S2:E1"}]
    }
  ],
  "Bear case": [
    {
      "text": "EBITDA margin fell 170 bps to 11.2% on higher copper prices; the MD expects to pass costs on within two quarters.",
      "citations": ["S3"],
      "evidence": [{"id": "S3:E5"}, {"id": "S3:E10"}]
    },
    {
      "text": "Receivable days rose from 78 to 96 over the past year, mainly due to two state utility customers.",
      "citations": ["S2"],
      "evidence": [{"id": "S2:E5"}]
    },
    {
      "text": "A CGST demand of ₹46.3 crore (FY20-21 and FY21-22 ITC) was received; the company intends to file an appeal.",
      "citations": ["S7"],
      "evidence": [{"id": "S7:E1"}, {"id": "S7:E2"}]
    }
  ],
